    /// Parse `AllocationUsageDeclaration`
    pub fn parse_allocation_usage_declaration(&mut self) -> Result<AllocationUsageDeclaration> {
        let _entry_pos = self.pos;
        if !self.enter_rule("AllocationUsageDeclaration") {
            return Err(ParseError { message: "left-recursive entry into AllocationUsageDeclaration".into(), span: self.current_span() });
        }
        self.push_rule_context("AllocationUsageDeclaration", _entry_pos);
        let _result: Result<AllocationUsageDeclaration> = (|| {
        let start = self.current_span();
        let saved_alt = self.save();
        let mut best_alt_pos: Option<usize> = None;
        self.restore(saved_alt);
        if (|| -> std::result::Result<(), ParseError> {
            self.expect(TokenKind::Allocation)?;
            self.parse_usage_declaration()?;
            let saved = self.save();
            let _: std::result::Result<(), ParseError> = (|| {
                self.expect(TokenKind::Allocate)?;
                self.parse_connector_part()?;
                Ok(())
            })().map_err(|e| { self.restore(saved); e });
            Ok(())
        })().is_ok() {
            let end = self.save();
            if best_alt_pos.map_or(true, |b| end > b) { best_alt_pos = Some(end); }
        }
        self.restore(saved_alt);
        if (|| -> std::result::Result<(), ParseError> {
            self.expect(TokenKind::Allocate)?;
            self.parse_connector_part()?;
            Ok(())
        })().is_ok() {
            let end = self.save();
            if best_alt_pos.map_or(true, |b| end > b) { best_alt_pos = Some(end); }
        }
        match best_alt_pos {
            Some(pos) => self.pos = pos,
            None => return Err(ParseError { message: "no alternative matched".into(), span: self.current_span() }),
        }

        let end = self.current_span();
        Ok(AllocationUsageDeclaration {
            span: start.merge(end),
        })
        })();
        self.pop_rule_context();
        self.leave_rule(_entry_pos, "AllocationUsageDeclaration");
        _result
    }

