    /// Parse `InterfaceNonOccurrenceUsageElement`
    pub fn parse_interface_non_occurrence_usage_element(&mut self) -> Result<InterfaceNonOccurrenceUsageElement> {
        let _entry_pos = self.pos;
        if !self.enter_rule("InterfaceNonOccurrenceUsageElement") {
            return Err(ParseError { message: "left-recursive entry into InterfaceNonOccurrenceUsageElement".into(), span: self.current_span() });
        }
        self.push_rule_context("InterfaceNonOccurrenceUsageElement", _entry_pos);
        let _result: Result<InterfaceNonOccurrenceUsageElement> = (|| {
        let alt_saved = self.save();
        let mut best: Option<(InterfaceNonOccurrenceUsageElement, usize)> = None;

        self.restore(alt_saved);
        if let Ok(v) = self.parse_reference_usage() {
            let end = self.pos;
            if best.as_ref().map_or(true, |(_, best_end)| end > *best_end) {
                best = Some((InterfaceNonOccurrenceUsageElement::ReferenceUsage(Box::new(v)), end));
            }
        }

        self.restore(alt_saved);
        if let Ok(v) = self.parse_attribute_usage() {
            let end = self.pos;
            if best.as_ref().map_or(true, |(_, best_end)| end > *best_end) {
                best = Some((InterfaceNonOccurrenceUsageElement::AttributeUsage(Box::new(v)), end));
            }
        }

        self.restore(alt_saved);
        if let Ok(v) = self.parse_enumeration_usage() {
            let end = self.pos;
            if best.as_ref().map_or(true, |(_, best_end)| end > *best_end) {
                best = Some((InterfaceNonOccurrenceUsageElement::EnumerationUsage(Box::new(v)), end));
            }
        }

        self.restore(alt_saved);
        if let Ok(v) = self.parse_binding_connector_as_usage() {
            let end = self.pos;
            if best.as_ref().map_or(true, |(_, best_end)| end > *best_end) {
                best = Some((InterfaceNonOccurrenceUsageElement::BindingConnectorAsUsage(Box::new(v)), end));
            }
        }

        self.restore(alt_saved);
        if let Ok(v) = self.parse_succession_as_usage() {
            let end = self.pos;
            if best.as_ref().map_or(true, |(_, best_end)| end > *best_end) {
                best = Some((InterfaceNonOccurrenceUsageElement::SuccessionAsUsage(Box::new(v)), end));
            }
        }

        match best {
            Some((result, end_pos)) => {
                self.pos = end_pos;
                Ok(result)
            }
            None => Err(ParseError { message: "expected InterfaceNonOccurrenceUsageElement".into(), span: self.current_span() })
        }
        })();
        self.pop_rule_context();
        self.leave_rule(_entry_pos, "InterfaceNonOccurrenceUsageElement");
        _result
    }

