    /// Parse `ExtendedUsage`
    pub fn parse_extended_usage(&mut self) -> Result<ExtendedUsage> {
        let _entry_pos = self.pos;
        if !self.enter_rule("ExtendedUsage") {
            return Err(ParseError { message: "left-recursive entry into ExtendedUsage".into(), span: self.current_span() });
        }
        self.push_rule_context("ExtendedUsage", _entry_pos);
        let _result: Result<ExtendedUsage> = (|| {
        let start = self.current_span();
        let mut usage_extension_keyword = Vec::new();
        self.parse_unextended_usage_prefix()?;
        let mut _glr_stop_positions: Vec<usize> = Vec::new();
        let v = self.parse_usage_extension_keyword()?;
        usage_extension_keyword.push(v);
        _glr_stop_positions.push(self.pos);
        loop {
            let saved = self.save();
            let ok: std::result::Result<(), ParseError> = (|| {
                let v = self.parse_usage_extension_keyword()?;
                usage_extension_keyword.push(v);
                Ok(())
            })();
            if ok.is_err() { self.restore(saved); break; }
            if self.save() == saved { break; } // no progress
            _glr_stop_positions.push(self.pos);
        }
        while _glr_stop_positions.len() > 1 && self.is_current_pos_excluded() {
            _glr_stop_positions.pop();
            usage_extension_keyword.pop();
            self.pos = *_glr_stop_positions.last().unwrap();
        }
        self.parse_usage()?;

        let end = self.current_span();
        Ok(ExtendedUsage {
            span: start.merge(end),
            usage_extension_keyword,
        })
        })();
        self.pop_rule_context();
        self.leave_rule(_entry_pos, "ExtendedUsage");
        _result
    }

