    /// Parse `ViewDefinitionBody`
    pub fn parse_view_definition_body(&mut self) -> Result<ViewDefinitionBody> {
        let _entry_pos = self.pos;
        if !self.enter_rule("ViewDefinitionBody") {
            return Err(ParseError { message: "left-recursive entry into ViewDefinitionBody".into(), span: self.current_span() });
        }
        self.push_rule_context("ViewDefinitionBody", _entry_pos);
        let _result: Result<ViewDefinitionBody> = (|| {
        let start = self.current_span();
        let mut view_definition_body_item = Vec::new();
        let saved_alt = self.save();
        let mut best_alt_pos: Option<usize> = None;
        self.restore(saved_alt);
        if (|| -> std::result::Result<(), ParseError> {
            self.expect(TokenKind::LBrace)?;
            let mut _glr_stop_positions: Vec<usize> = vec![self.pos];
            loop {
                let saved = self.save();
                let ok: std::result::Result<(), ParseError> = (|| {
                    let v = self.parse_view_definition_body_item()?;
                    view_definition_body_item.push(v);
                    Ok(())
                })();
                if ok.is_err() { self.restore(saved); break; }
                if self.save() == saved { break; } // no progress
                _glr_stop_positions.push(self.pos);
            }
            while _glr_stop_positions.len() > 1 && self.is_current_pos_excluded() {
                _glr_stop_positions.pop();
                view_definition_body_item.pop();
                self.pos = *_glr_stop_positions.last().unwrap();
            }
            self.expect(TokenKind::RBrace)?;
            Ok(())
        })().is_ok() {
            let end = self.save();
            if best_alt_pos.map_or(true, |b| end > b) { best_alt_pos = Some(end); }
        }
        self.restore(saved_alt);
        if (|| -> std::result::Result<(), ParseError> {
            self.expect(TokenKind::Semi)?;
            Ok(())
        })().is_ok() {
            let end = self.save();
            if best_alt_pos.map_or(true, |b| end > b) { best_alt_pos = Some(end); }
        }
        match best_alt_pos {
            Some(pos) => self.pos = pos,
            None => return Err(ParseError { message: "no alternative matched".into(), span: self.current_span() }),
        }

        let end = self.current_span();
        Ok(ViewDefinitionBody {
            span: start.merge(end),
            view_definition_body_item,
        })
        })();
        self.pop_rule_context();
        self.leave_rule(_entry_pos, "ViewDefinitionBody");
        _result
    }

